<?php
return function(PDO $pdo): void {
    $pdo->exec("CREATE TABLE IF NOT EXISTS users (id INT AUTO_INCREMENT PRIMARY KEY, username VARCHAR(120) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, fullname VARCHAR(255) NOT NULL, email VARCHAR(255) NULL, role VARCHAR(50) NOT NULL DEFAULT 'member', provider VARCHAR(50) NOT NULL DEFAULT 'local', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
    $pdo->exec("CREATE TABLE IF NOT EXISTS projects (id VARCHAR(64) PRIMARY KEY, owner_user_id INT NULL, title VARCHAR(255) NOT NULL, description TEXT NULL, category VARCHAR(100) NULL, status VARCHAR(50) DEFAULT 'draft', publication_status VARCHAR(50) DEFAULT 'draft', authentication_status VARCHAR(50) DEFAULT 'missing', image_path VARCHAR(255) NULL, participation_info TEXT NULL, tags_json TEXT NULL, authenticated_document_id INT NULL, authenticated_at DATETIME NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
    $pdo->exec("CREATE TABLE IF NOT EXISTS partners (id VARCHAR(80) PRIMARY KEY,name VARCHAR(255) NOT NULL,description TEXT NULL,image_path VARCHAR(500) NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
};
